-- Local/Test Center ledger only. It has no product, signing, gateway or execution consumer.
CREATE TABLE IF NOT EXISTS effective_authority_scopes (scope_hash char(64) PRIMARY KEY CHECK(scope_hash~'^[a-f0-9]{64}$'), operator_test_id text NOT NULL, tenant_fingerprint text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE n text; ns text[]:=ARRAY['effective_authority_registry_snapshots','effective_authority_source_receipts','effective_authority_owner_heads','effective_authority_gate_results','effective_authority_gate_edges','effective_authority_input_manifests','effective_authority_decisions','effective_authority_reason_projections','effective_authority_explanations','effective_authority_enforcement_comparisons','effective_authority_transitions','effective_authority_request_claims','effective_authority_conflicts','effective_authority_test_center_bundles']; BEGIN FOREACH n IN ARRAY ns LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS %I (artifact_hash char(64) PRIMARY KEY CHECK(artifact_hash~''^[a-f0-9]{64}$''), scope_hash char(64) NOT NULL REFERENCES effective_authority_scopes(scope_hash), operator_test_id text NOT NULL, idempotency_key text, request_hash char(64), sequence integer CHECK(sequence IS NULL OR sequence>0), predecessor_hash char(64), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_hash,artifact_hash))',n); END LOOP; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS effective_authority_owner_sequence ON effective_authority_owner_heads(scope_hash,(payload->>'gate_id'),sequence);
CREATE UNIQUE INDEX IF NOT EXISTS effective_authority_claim_idempotency ON effective_authority_request_claims(operator_test_id,idempotency_key);
CREATE INDEX IF NOT EXISTS effective_authority_decision_current ON effective_authority_decisions(scope_hash,created_at DESC);
CREATE OR REPLACE FUNCTION effective_authority_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'effective_authority_append_only'; END $$;
DO $$ DECLARE n text; ns text[]:=ARRAY['effective_authority_scopes','effective_authority_registry_snapshots','effective_authority_source_receipts','effective_authority_owner_heads','effective_authority_gate_results','effective_authority_gate_edges','effective_authority_input_manifests','effective_authority_decisions','effective_authority_reason_projections','effective_authority_explanations','effective_authority_enforcement_comparisons','effective_authority_transitions','effective_authority_request_claims','effective_authority_conflicts','effective_authority_test_center_bundles']; BEGIN FOREACH n IN ARRAY ns LOOP EXECUTE format('DROP TRIGGER IF EXISTS effective_authority_immutable ON %I',n); EXECUTE format('CREATE TRIGGER effective_authority_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION effective_authority_append_only()',n); END LOOP; END $$;
DROP VIEW IF EXISTS effective_authority_current_fixture_projection;
CREATE VIEW effective_authority_current_fixture_projection AS SELECT DISTINCT ON (scope_hash) scope_hash, payload->>'capability' AS capability, payload->>'phase' AS phase, payload->'reasons' AS reason_codes, sequence, created_at FROM effective_authority_decisions ORDER BY scope_hash, sequence DESC NULLS LAST, artifact_hash DESC;
